/**
 * Lazy loader for the optional `ai` peer dependency. Deterministic suites and custom
 * executors never load the AI SDK; everything model-backed funnels through
 * here, so the install weight is opt-in and the failure mode is one clear
 * MODEL_UNAVAILABLE instead of a module-resolution crash at startup.
 */
import { isModelInstance } from '../config/agent.js';
import { ConfigurationError } from '../internal/errors.js';
import { realmSlot } from '../internal/realm-slot.js';
import { AgentError } from './error.js';
/**
 * Narrows a structurally verified model instance to the SDK model type. The
 * one place this cast lives; everything downstream takes the checked type.
 * It sits here, at the SDK boundary, and not in config resolution: the
 * resolved config is in the type closure of the `e2e` entry, and this is the
 * only module the `ai` types may enter from.
 */
export function asSdkLanguageModel(instance) {
    if (!isModelInstance(instance)) {
        throw new ConfigurationError('INVALID_CONFIG', 'value is not an AI SDK language model instance');
    }
    return instance;
}
/**
 * The cache lives on `globalThis`, not in module state: config and test
 * modules may import a copy of e2e other than the runner's, so an executor
 * constructed in config code and the runner's own model plumbing would
 * otherwise hold two separate caches, and two separate `ai` module instances
 * whose error classes fail each other's instanceof checks. One slot, one SDK
 * instance, every copy.
 */
const cacheSlot = realmSlot('e2e.ai-sdk.v1');
function cache() {
    let state = cacheSlot.get(globalThis);
    if (state === undefined) {
        state = {};
        cacheSlot.set(globalThis, state);
    }
    return state;
}
/** Loads and caches the AI SDK, or fails with MODEL_UNAVAILABLE. */
export async function loadAiSdk() {
    const state = cache();
    if (state.loaded !== undefined)
        return state.loaded;
    if (state.failure !== undefined)
        throw missing(state.failure);
    try {
        state.loaded = await import('ai');
        return state.loaded;
    }
    catch (cause) {
        state.failure = cause instanceof Error ? cause : new Error(String(cause));
        throw missing(state.failure);
    }
}
/**
 * The SDK when the optional peer is installed, else undefined: for the seams
 * that have a way to do their job without it.
 */
export async function loadAiSdkIfInstalled() {
    return loadAiSdk().catch(() => undefined);
}
/** The SDK when an earlier call loaded it, else undefined; never loads it. */
export function loadedAiSdk() {
    return cache().loaded;
}
/**
 * The already-loaded SDK, for the few synchronous seams (error-class checks)
 * that run strictly after an async caller primed the cache.
 */
export function aiSdk() {
    const state = cache();
    if (state.loaded === undefined) {
        throw new AgentError('MODEL_UNAVAILABLE', 'the AI SDK has not been loaded; load the ai package before reading the model');
    }
    return state.loaded;
}
function missing(cause) {
    return new AgentError('MODEL_UNAVAILABLE', 'the "ai" package is not installed; model-backed agent calls require the optional ' +
        'peer dependency ai@^7 — install it, or configure an agent that brings ' +
        'its own model transport', { cause });
}
